function readEnv() { const env = {}; for (const line of fs.readFileSync(path.join(SERVER, '.env'), 'utf8').split(/\r?\n/)) { const m = line.match(/^([^#=]+)=(.*)$/); if (m) env[m[1].trim()] = m[2].trim(); } return env; }
function rec(group, id, name, ok, detail = {}) { const item = { id, name, status: ok ? 'PASS' : 'FAIL', detail, at: new Date().toISOString() }; ev[group].push(item); if (!ok) ev.defects.push(item); console.log(`${ok ? 'PASS' : 'FAIL'} ${group.toUpperCase()} ${id} ${name}`); return ok; }
function assert(group, id, name, cond, detail = {}) { return rec(group, id, name, Boolean(cond), detail); }
async function expectError(group, id, name, fn, includes) { try { await fn(); rec(group, id, name, false, { expected: includes, actual: 'no error' }); } catch (e) { assert(group, id, name, !includes || String(e.message).includes(includes), { message: e.message, status: e.status }); } }
async function api(uri, options = {}) { const headers = { 'content-type': 'application/json', ...(options.headers || {}) }; if (global.token) headers.authorization = `Bearer ${global.token}`; const r = await fetch(`${API}${uri}`, { ...options, headers }); const text = await r.text(); let body; try { body = text ? JSON.parse(text) : null; } catch { body = text; } if (!r.ok || (body && body.code >= 400)) { const e = new Error(body?.message || text || `HTTP ${r.status}`); e.status = r.status; e.body = body; throw e; } return body && Object.prototype.hasOwnProperty.call(body, 'data') ? body.data : body; }
async function db(pool, q, inputs = {}) { const req = pool.request(); for (const [k, v] of Object.entries(inputs)) req.input(k, v); return (await req.query(q)).recordset; }
async function one(pool, q, inputs = {}) { return (await db(pool, q, inputs))[0]; }
async function insert(pool, table, values) { const cols = Object.keys(values); const req = pool.request(); cols.forEach((c) => req.input(c, values[c])); return (await req.query(`insert into ${table} (${cols.map((c) => `[${c}]`).join(',')}) output inserted.id values (${cols.map((c) => `@${c}`).join(',')})`)).recordset[0].id; }
async function prepare(pool) { const suffix = RUN.replace(/\D/g, '').slice(-10); const now = new Date(); const common = { created_at: now, updated_at: now, is_deleted: 0 }; const password = `P4_${suffix}_Pwd`; const username = `p4acc_${suffix}`; const userId = await insert(pool, 'sys_user', { username, password: bcrypt.hashSync(password, 10), real_name: 'P4验收', email: '', phone: '', dept_id: null, emp_id: null, avatar: '', status: 1, ...common }); const supplierId = await insert(pool, 'master_supplier', { supplier_code: `P4SUP_${suffix}`, supplier_name: `P4供应商_${suffix}`, short_name: `P4SUP_${suffix}`, supplier_type: 1, contact_person: 'P4', contact_phone: '', email: '', address: '', payment_term_id: null, buyer_id: null, tax_number: '', bank_name: '', bank_account: '', status: 1, remark: RUN, ...common }); const warehouseId = await insert(pool, 'master_warehouse', { warehouse_code: `P4WH_${suffix}`, warehouse_name: `P4仓_${suffix}`, warehouse_type: 1, parent_id: null, manager_id: null, address: '', is_default: 0, status: 1, remark: RUN, ...common }); const unitId = await insert(pool, 'master_unit', { unit_code: `P4U_${suffix}`, unit_name: '个', unit_type: 1, precision: 4, status: 1, remark: RUN, ...common }); const materialId = await insert(pool, 'master_material', { material_code: `P4MAT_${suffix}`, material_name: `P4物料_${suffix}`, material_spec: 'P4-SPEC', category_id: null, unit_id: unitId, material_type: 2, purchase_type: 1, barcode: '', default_warehouse: warehouseId, safety_stock: 0, min_order_qty: 0, lead_time: 0, standard_cost: 0, sale_price: 0, is_batch_manage: 0, is_serial_manage: 0, shelf_life_days: 0, status: 1, remark: RUN, ...common }); const currencyId = await insert(pool, 'master_currency', { currency_code: `P${suffix.slice(-5)}`, currency_name: `P4币_${suffix}`, currency_symbol: 'CNY', exchange_rate: 1, is_base: 0, status: 1, remark: RUN, ...common }); const paymentTermId = await insert(pool, 'master_payment_term', { term_code: `P4PT_${suffix}`, term_name: `P4月结_${suffix}`, term_type: 3, credit_days: 30, advance_ratio: 0, stage1_ratio: 0, stage2_ratio: 0, stage3_ratio: 0, status: 1, remark: RUN, ...common }); const orgId = randomUUID(); const login = await api('/auth/login', { method: 'POST', body: JSON.stringify({ username, password }) }); global.token = login.accessToken; return { suffix, userId, supplierId, warehouseId, unitId, materialId, currencyId, paymentTermId, orgId } }
async function createOrder(ctx, key, requestQty, orderQty, unitPrice = 10) { const pr = await api('/purchase-requests', { method: 'POST', body: JSON.stringify({ orgId: ctx.orgId, requestDate: '2026-07-20', remark: `${RUN}-${key}`, entries: [{ purchaseOrgId: ctx.orgId, materialId: ctx.materialId, materialCode: `P4MAT_${ctx.suffix}`, materialName: `P4物料_${ctx.suffix}`, unitId: ctx.unitId, unitName: '个', requestQty, estimatedPrice: unitPrice, supplierId: ctx.supplierId, warehouseId: ctx.warehouseId }] }) }); await api(`/purchase-requests/${pr.id}/submit`, { method: 'POST' }); const pra = await api(`/purchase-requests/${pr.id}/approve`, { method: 'POST' }); const po = await api('/purchase-orders/from-request', { method: 'POST', body: JSON.stringify({ idempotencyKey: `${RUN}-PO-${key}`, supplierId: ctx.supplierId, contractNo: `HT-${RUN}-${key}`, orderDate: '2026-07-20', currencyId: ctx.currencyId, paymentTermId: ctx.paymentTermId, lines: [{ requestEntryId: pra.entries[0].id, quantity: orderQty, unitPrice, taxRate: 13, warehouseId: ctx.warehouseId, checkIncoming: false }] }) }); await api(`/purchase-orders/${po.id}/submit`, { method: 'POST' }); const poa = await api(`/purchase-orders/${po.id}/approve`, { method: 'POST' }); return { request: pra, order: poa }; }
async function createInbound(ctx, key, qty = 7, unitPrice = 50) { const flow = await createOrder(ctx, key, qty, qty, unitPrice); const rn = await api('/purchase-receive-notices/from-order', { method: 'POST', body: JSON.stringify({ purchaseOrderId: flow.order.id, stockOrgId: ctx.orgId, purchaseOrgId: ctx.orgId, receiveBatchNo: `RB-${RUN}-${key}`, receiveDate: '2026-07-20', needCheck: false, lines: [{ orderEntryId: flow.order.entries[0].id, quantity: qty, checkIncoming: false, warehouseId: ctx.warehouseId }] }) }); await api(`/purchase-receive-notices/${rn.id}/submit`, { method: 'POST' }); const rna = await api(`/purchase-receive-notices/${rn.id}/approve`, { method: 'POST' }); const inbound = await api('/inventory-in/from-receive-notices', { method: 'POST', body: JSON.stringify({ idempotencyKey: `${RUN}-IN-${key}`, inDate: '2026-07-20', settleOrgId: ctx.orgId, ownerType: 'BD_OwnerOrg', ownerId: ctx.orgId, entries: [{ sourceReceiveNoticeEntryId: rna.entries[0].id, quantity: qty, warehouseId: ctx.warehouseId }] }) }); await api(`/inventory-in/${inbound.id}/submit`, { method: 'POST' }); const ina = await api(`/inventory-in/${inbound.id}/approve`, { method: 'POST', body: JSON.stringify({ approvedBy: 'P4' }) }); return { ...flow, receive: rna, inbound: ina }; }
async function runOrderChange(pool, ctx) { const flow = await createOrder(ctx, 'CHG', 15, 10, 10); ev.ids.changeOrderId = flow.order.id; const line = flow.order.entries[0]; const dto = { idempotencyKey: `${RUN}-CHG-1`, orderId: flow.order.id, changeDate: '2026-07-20', changeReason: 'P4数量价格交期仓库备注变更', remark: RUN, entries: [{ orderEntryId: line.id, newOrderQty: 12, newUnitPrice: 11, newDeliveryDate: '2026-08-01', newWarehouseId: randomUUID(), newRemark: 'P4变更后备注' }] }; const chg = await api('/purchase-order-changes/from-order', { method: 'POST', body: JSON.stringify(dto) }); const same = await api('/purchase-order-changes/from-order', { method: 'POST', body: JSON.stringify(dto) }); assert('p4', 'P4-CHG-01', '订单变更创建及同键同载荷幂等', chg.id === same.id && chg.statusCode === 'DRAFT', { id: chg.id, status: chg.statusCode }); await expectError('p4', 'P4-CHG-02', '订单变更同键不同载荷冲突', () => api('/purchase-order-changes/from-order', { method: 'POST', body: JSON.stringify({ ...dto, changeReason: '不同载荷' }) }), '载荷不一致'); await expectError('p4', 'P4-CHG-03', '同采购订单只允许一个未生效变更', () => api('/purchase-order-changes/from-order', { method: 'POST', body: JSON.stringify({ ...dto, idempotencyKey: `${RUN}-CHG-ACTIVE`, changeReason: '第二张未生效' }) }), '已存在有效未生效'); await api(`/purchase-order-changes/${chg.id}/submit`, { method: 'POST' }); const approved = await api(`/purchase-order-changes/${chg.id}/approve`, { method: 'POST', body: JSON.stringify({ operatedBy: 'P4' }) }); const approvedAgain = await api(`/purchase-order-changes/${chg.id}/approve`, { method: 'POST', body: JSON.stringify({ operatedBy: 'P4' }) }); assert('p4', 'P4-CHG-04', '订单变更审核生效及重复审核幂等', approved.statusCode === 'APPROVED' && approved.effectiveStatus === 'EFFECTIVE' && approvedAgain.id === approved.id, { status: approved.statusCode, effectiveStatus: approved.effectiveStatus }); const poEntry = await one(pool, 'select order_qty, unit_price, amount, tax_amount, net_amount, warehouse_id, remark from biz_purchase_order_entry where id=@id', { id: line.id }); const prEntry = await one(pool, 'select purchased_qty from purchase_request_entry where id=@id', { id: line.sourceRequestEntryId }); assert('p4', 'P4-CHG-05', '变更审核反写订单明细和申请已采购数量', Number(poEntry.order_qty) === 12 && Number(poEntry.unit_price) === 11 && Number(poEntry.amount) === 132 && Number(poEntry.tax_amount) === 17.16 && Number(prEntry.purchased_qty) === 12, { poEntry, prEntry }); const hist = await api(`/purchase-order-changes/order/${flow.order.id}`); assert('p4', 'P4-CHG-06', '订单变更历史可按订单追溯', Array.isArray(hist) && hist.some((x) => x.id === chg.id), { count: hist.length }); const draft2 = await api('/purchase-order-changes/from-order', { method: 'POST', body: JSON.stringify({ idempotencyKey: `${RUN}-CHG-CANCEL`, orderId: flow.order.id, changeReason: '取消释放', entries: [{ orderEntryId: line.id, newUnitPrice: 12 }] }) }); await api(`/purchase-order-changes/${draft2.id}/cancel`, { method: 'POST', body: JSON.stringify({ operatedBy: 'P4', reason: '释放唯一约束' }) }); const draft3 = await api('/purchase-order-changes/from-order', { method: 'POST', body: JSON.stringify({ idempotencyKey: `${RUN}-CHG-RECREATE`, orderId: flow.order.id, changeReason: '取消后重建', entries: [{ orderEntryId: line.id, newUnitPrice: 13 }] }) }); assert('p4', 'P4-CHG-07', '取消未生效变更释放唯一约束并可重建', draft2.id !== draft3.id && draft3.statusCode === 'DRAFT', { canceled: draft2.id, recreated: draft3.id }); const recv = await createOrder(ctx, 'CHG-RECV', 10, 10, 10); const rn = await api('/purchase-receive-notices/from-order', { method: 'POST', body: JSON.stringify({ purchaseOrderId: recv.order.id, stockOrgId: ctx.orgId, purchaseOrgId: ctx.orgId, receiveBatchNo: `RB-${RUN}-CHG-RECV`, receiveDate: '2026-07-20', needCheck: false, lines: [{ orderEntryId: recv.order.entries[0].id, quantity: 6, checkIncoming: false, warehouseId: ctx.warehouseId }] }) }); await api(`/purchase-receive-notices/${rn.id}/submit`, { method: 'POST' }); await api(`/purchase-receive-notices/${rn.id}/approve`, { method: 'POST' }); await expectError('p4', 'P4-CHG-08', '新数量小于已收料数量禁止创建变更', () => api('/purchase-order-changes/from-order', { method: 'POST', body: JSON.stringify({ idempotencyKey: `${RUN}-CHG-LOW`, orderId: recv.order.id, changeReason: '低于已收料', entries: [{ orderEntryId: recv.order.entries[0].id, newOrderQty: 5 }] }) }), '已收料'); }
async function runReconciliationAndReports(pool, ctx) { const flow = await createInbound(ctx, 'REC', 7, 50); ev.ids.reconciliationOrderId = flow.order.id; assert('regression', 'P0-REG-01', 'P0标准采购入库暂估应付回归', flow.inbound.statusCode === 'APPROVED' && flow.inbound.payableGenerationStatus === 'GENERATED', { inNo: flow.inbound.inNo, payableNo: flow.inbound.payableNo }); const beforePay = await one(pool, 'select count(*) c from fin_payable where is_deleted=0'); const dto = { idempotencyKey: `${RUN}-REC-1`, supplierId: ctx.supplierId, purchaseOrgId: ctx.orgId, settleOrgId: ctx.orgId, currencyId: ctx.currencyId, periodStart: '2026-07-20', periodEnd: '2026-07-20', purchaseOrderId: flow.order.id, reconciliationDate: '2026-07-20', remark: RUN }; const rec1 = await api('/purchase-reconciliations/generate', { method: 'POST', body: JSON.stringify(dto) }); const same = await api('/purchase-reconciliations/generate', { method: 'POST', body: JSON.stringify(dto) }); assert('p4', 'P4-REC-01', '对账生成及同键同载荷幂等', rec1.id === same.id && rec1.entries?.length === 1, { id: rec1.id, entries: rec1.entries?.length }); const e0 = rec1.entries[0]; assert('p4', 'P4-REC-02', '对账明细来源追溯入库与暂估应付', e0.businessSourceType === 'PURCHASE_INBOUND' && e0.payableType === 'ESTIMATED' && e0.sourceOrderId === flow.order.id && Number(e0.businessQty) === 7 && Number(e0.payableQty) === 7, { entry: e0 }); await expectError('p4', 'P4-REC-03', '对账同键不同载荷冲突', () => api('/purchase-reconciliations/generate', { method: 'POST', body: JSON.stringify({ ...dto, remark: '不同载荷' }) }), '载荷不一致'); const activeSame = await api('/purchase-reconciliations/generate', { method: 'POST', body: JSON.stringify({ ...dto, idempotencyKey: `${RUN}-REC-ACTIVE` }) }); assert('p4', 'P4-REC-04', '同维度有效对账未取消前返回同一有效单', activeSame.id === rec1.id, { id: activeSame.id }); await api(`/purchase-reconciliations/${rec1.id}/cancel`, { method: 'POST', body: JSON.stringify({ canceledBy: 'P4', reason: '释放范围' }) }); const rec2 = await api('/purchase-reconciliations/generate', { method: 'POST', body: JSON.stringify({ ...dto, idempotencyKey: `${RUN}-REC-2` }) }); assert('p4', 'P4-REC-05', '对账取消后释放范围并可重建', rec2.id !== rec1.id && rec2.statusCode === 'GENERATED', { oldId: rec1.id, newId: rec2.id }); const line = rec2.entries[0]; await expectError('p4', 'P4-REC-06', '非零差异确认原因必填', () => api(`/purchase-reconciliations/${rec2.id}/confirm`, { method: 'POST', body: JSON.stringify({ confirmedBy: 'P4', entries: [{ entryId: line.id, confirmedQty: Number(line.payableQty) + 1, confirmedUnitPrice: Number(line.payableUnitPrice), confirmedUntaxedAmount: Number(line.payableUntaxedAmount), confirmedTaxAmount: Number(line.payableTaxAmount), confirmedTotalAmount: Number(line.payableTotalAmount) }] }) }), '差异原因必填'); const confirmed = await api(`/purchase-reconciliations/${rec2.id}/confirm`, { method: 'POST', body: JSON.stringify({ confirmedBy: 'P4', entries: [{ entryId: line.id, confirmedQty: Number(line.payableQty) + 1, confirmedUnitPrice: Number(line.payableUnitPrice), confirmedUntaxedAmount: Number(line.payableUntaxedAmount), confirmedTaxAmount: Number(line.payableTaxAmount), confirmedTotalAmount: Number(line.payableTotalAmount), differenceReason: 'P4确认数量差异', remark: 'P4确认备注' }] }) }); const afterPay = await one(pool, 'select count(*) c from fin_payable where is_deleted=0'); assert('p4', 'P4-REC-07', '对账确认只记录差异不自动调账', confirmed.statusCode === 'CONFIRMED' && Number(afterPay.c) === Number(beforePay.c), { status: confirmed.statusCode, before: beforePay.c, after: afterPay.c }); const recDb = await one(pool, 'select status, confirmed_qty, difference_qty from biz_purchase_reconciliation where id=@id', { id: rec2.id }); assert('p4', 'P4-REC-08', '对账确认数量和差异落库', Number(recDb.status) === 1 && Number(recDb.confirmed_qty) === 8 && Number(recDb.difference_qty) === 1, recDb); const list = await api(`/purchase-reconciliations?page=1&pageSize=20&supplierId=${ctx.supplierId}&purchaseOrgId=${ctx.orgId}`); assert('p4', 'P4-REC-09', '对账列表可按供应商采购组织查询', list.list.some((x) => x.id === rec2.id), { total: list.total }); const reports = [ ['order-execution-summary', 'list'], ['order-execution-detail', 'list'], ['consume-summary', 'list'], ['overview', 'object'] ]; for (const [name, mode] of reports) { const data = await api(`/purchase-reports/${name}?purchaseOrgId=${ctx.orgId}&supplierId=${ctx.supplierId}&page=1&pageSize=20`); assert('p4', `P4-RPT-${name.toUpperCase().replace(/-/g, '-')}`, `采购报表${name}可查询`, mode === 'list' ? Array.isArray(data.list) : !!data && typeof data === 'object', { sample: mode === 'list' ? { total: data.total, first: data.list[0] } : data }); }
  const ret = await api('/purchase-returns/from-inbound', { method: 'POST', body: JSON.stringify({ inventoryInId: flow.inbound.id, idempotencyKey: `${RUN}-RET`, returnMode: 'DEDUCTION', reason: 'P4回归扣款退料', returnDate: '2026-07-20', lines: [{ inventoryInEntryId: flow.inbound.entries[0].id, quantity: 1 }] }) }); await api(`/purchase-returns/${ret.id}/submit`, { method: 'POST' }); const reta = await api(`/purchase-returns/${ret.id}/approve`, { method: 'POST', body: JSON.stringify({ operatedBy: 'P4' }) }); assert('regression', 'P1-REG-01', 'P1直接退料扣款红字应付回归', reta.statusCode === 'APPROVED' && reta.payableGenerationStatus === 'GENERATED', { returnNo: reta.returnNo, payableNo: reta.payableNo }); }
async function main() { const env = readEnv(); const pool = await sql.connect({ server: env.DB_MSSQL_HOST || 'localhost', port: +(env.DB_MSSQL_PORT || 1433), user: env.DB_MSSQL_USERNAME, password: env.DB_MSSQL_PASSWORD, database: env.DB_MSSQL_DATABASE, options: { encrypt: false, trustServerCertificate: true } }); try { const swagger = await (await fetch(`${API}/docs-json`)).json(); const routes = ['/api/purchase-order-changes','/api/purchase-order-changes/{id}','/api/purchase-order-changes/order/{orderId}','/api/purchase-order-changes/from-order','/api/purchase-order-changes/{id}/submit','/api/purchase-order-changes/{id}/approve','/api/purchase-order-changes/{id}/reject','/api/purchase-order-changes/{id}/cancel','/api/purchase-reconciliations/generate','/api/purchase-reconciliations','/api/purchase-reconciliations/{id}','/api/purchase-reconciliations/{id}/confirm','/api/purchase-reconciliations/{id}/cancel','/api/purchase-reports/order-execution-summary','/api/purchase-reports/order-execution-detail','/api/purchase-reports/consume-summary','/api/purchase-reports/overview']; assert('p4', 'P4-ROUTE-01', 'Swagger已注册17条P4路径', routes.every((r) => swagger.paths?.[r]), { missing: routes.filter((r) => !swagger.paths?.[r]) }); const ctx = await prepare(pool); ev.ids = ctx; await runOrderChange(pool, ctx); await runReconciliationAndReports(pool, ctx); } catch (e) { rec('p4', 'P4-UNHANDLED', 'P4复验脚本未捕获错误', false, { message: e.message, stack: e.stack, body: e.body }); } finally { ev.completedAt = new Date().toISOString(); ev.summary = { p4: { total: ev.p4.length, passed: ev.p4.filter((x) => x.status === 'PASS').length, failed: ev.p4.filter((x) => x.status === 'FAIL').length }, regression: { total: ev.regression.length, passed: ev.regression.filter((x) => x.status === 'PASS').length, failed: ev.regression.filter((x) => x.status === 'FAIL').length }, defects: ev.defects.length }; fs.writeFileSync(OUT, `${JSON.stringify(ev, null, 2)}\n`); await pool.close(); console.log(`evidence=${OUT}`); console.log(JSON.stringify(ev.summary)); if (ev.defects.length) process.exitCode = 1; } }
main();
